<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\DispatchService;Auth::requirePermission('TRIP_VIEW_CARRIER');$rows=DispatchService::carrierTrips((int)Auth::user()['id']);$pageTitle='Fleet Trips';require BASE_PATH.'/app/Views/layout/header.php';?><h1>Fleet trips</h1><div class="card table-wrap"><table><thead><tr><th>Trip</th><th>Load</th><th>Route</th><th>Truck / Driver</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['trip_ref'])?></td><td><?=h($r['load_ref'])?></td><td><?=h($r['origin_city'].' → '.$r['destination_city'])?></td><td><?=h($r['registration_number'].' · '.$r['driver_name'])?></td><td><span class="status-pill status-<?=h($r['current_status'])?>"><?=h(str_replace('_',' ',$r['current_status']))?></span></td><td><a href="<?=h(\App\Support\Url::to('tracking/view.php?id='.$r['trip_id']))?>">Track</a></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
